using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeCategory
{
    public const string Breakfast = "Breakfast";
    public const string Lunch = "Lunch";
    public const string Dinner = "Dinner";
    public const string Desserts = "Desserts";
    public const string Snacks = "Snacks";

    public static readonly string[] All = [Breakfast, Lunch, Dinner, Desserts, Snacks];
}

namespace RecipeCommunity.Models;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = GetSeedData();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void Add(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }

    private static List<Recipe> GetSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = RecipeCategory.Breakfast,
            Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder",
            Steps = "1. Mix dry ingredients.\n2. Whisk eggs and milk.\n3. Combine wet and dry.\n4. Cook on griddle until golden.",
            AverageRating = 4.5, RatingCount = 10
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = RecipeCategory.Breakfast,
            Ingredients = "2 slices sourdough\n1 ripe avocado\nSalt and pepper\nRed pepper flakes",
            Steps = "1. Toast bread.\n2. Mash avocado with salt and pepper.\n3. Spread on toast.\n4. Top with red pepper flakes.",
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = RecipeCategory.Lunch,
            Ingredients = "1 head romaine lettuce\nCaesar dressing\nCroutons\nParmesan cheese",
            Steps = "1. Chop lettuce.\n2. Toss with dressing.\n3. Add croutons and parmesan.",
            AverageRating = 4.0, RatingCount = 5
        },
        new()
        {
            Id = 4, Title = "Grilled Chicken Wrap", Category = RecipeCategory.Lunch,
            Ingredients = "Grilled chicken breast\nTortilla\nLettuce\nTomato\nRanch dressing",
            Steps = "1. Slice grilled chicken.\n2. Layer on tortilla with veggies.\n3. Drizzle ranch.\n4. Roll tightly.",
            AverageRating = 4.3, RatingCount = 7
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = RecipeCategory.Dinner,
            Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion\n3 cloves garlic",
            Steps = "1. Cook pasta.\n2. Sauté onion and garlic.\n3. Brown beef.\n4. Add tomatoes and simmer 20 min.\n5. Serve over pasta.",
            AverageRating = 4.7, RatingCount = 15
        },
        new()
        {
            Id = 6, Title = "Chocolate Chip Cookies", Category = RecipeCategory.Desserts,
            Ingredients = "2.25 cups flour\n1 cup butter\n0.75 cup sugar\n2 eggs\n2 cups chocolate chips",
            Steps = "1. Cream butter and sugar.\n2. Add eggs.\n3. Mix in flour.\n4. Fold in chocolate chips.\n5. Bake at 375°F for 10 min.",
            AverageRating = 4.8, RatingCount = 20
        },
        new()
        {
            Id = 7, Title = "Trail Mix", Category = RecipeCategory.Snacks,
            Ingredients = "1 cup almonds\n1 cup cashews\n0.5 cup raisins\n0.5 cup chocolate chips\n0.5 cup dried cranberries",
            Steps = "1. Combine all ingredients in a bowl.\n2. Mix well.\n3. Store in airtight container.",
            AverageRating = 3.9, RatingCount = 4
        }
    ];
}

