@page "/recipes/{Category}"

@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@Category Recipes</PageTitle>

<h1>@Category Recipes</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">
                            @recipe.AverageRating.ToString("F1") ★ (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"

@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

@if (_recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var line in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@line</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var line in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@(line.TrimStart("0123456789. ".ToCharArray()))</li>
        }
    </ol>

    <h3>Rating</h3>
    <p>@_recipe.AverageRating.ToString("F1") ★ (@_recipe.RatingCount ratings)</p>

    <StarRating RecipeId="@_recipe.Id" />

    <a href="/recipes/@_recipe.Category.ToLower()" class="btn btn-secondary mt-3">← Back to @_recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

@using RecipeCommunity.Models
@inject RecipeService RecipeService

<div class="my-3">
    <span>Rate this recipe: </span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-sm @(star <= _selectedRating ? "btn-warning" : "btn-outline-secondary")"
                @onclick="() => SubmitRating(star)"
                disabled="@_submitted">
            ★
        </button>
    }
    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

@using System.ComponentModel.DataAnnotations
@using RecipeCommunity.Models
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        Recipe submitted successfully! <a href="/recipe/@_newId">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label class="form-label">Title</label>
            <InputText @bind-Value="_model.Title" class="form-control" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect @bind-Value="_model.Category" class="form-select">
                <option value="">-- Select Category --</option>
                @foreach (var cat in RecipeCategory.All)
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients (one per line)</label>
            <InputTextArea @bind-Value="_model.Ingredients" class="form-control" rows="5" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps (one per line)</label>
            <InputTextArea @bind-Value="_model.Steps" class="form-control" rows="5" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private Recipe _model = new();
    private bool _submitted;
    private int _newId;

    private void HandleSubmit()
    {
        RecipeService.Add(_model);
        _newId = _model.Id;
        _submitted = true;
    }
}

